import { mkdtempSync, readFileSync, writeFileSync } from "node:fs";
import { tmpdir } from "node:os";
import { join } from "node:path";
import { afterEach, describe, expect, it } from "vitest";
import { loadConfig, saveConfig } from "../src/config/config.js";
import { ConfigSchema, captureSettings, extraStores, serverSettings } from "../src/config/schema.js";

// The shape 0.1.44 wrote, generated by that version's schema. Upgrading must
// read it as the same object and write it back unchanged.
const FULL_0_1_44 = readFileSync(join(__dirname, "fixtures", "config-0.1.44-full.json"), "utf8");
const MINIMAL_PARSED_0_1_44 = JSON.parse(
  readFileSync(join(__dirname, "fixtures", "config-0.1.44-minimal-parsed.json"), "utf8"),
);

const original = process.env.AGENT_JULIA_CONFIG;
afterEach(() => {
  process.env.AGENT_JULIA_CONFIG = original;
});

function tempConfig(): { path: string; dir: string } {
  const dir = mkdtempSync(join(tmpdir(), "aj-compat-"));
  const path = join(dir, "config.json");
  process.env.AGENT_JULIA_CONFIG = path;
  return { path, dir };
}

describe("a config written by 0.1.44", () => {
  it("parses to the same object, with no new keys", () => {
    const raw = JSON.parse(FULL_0_1_44);
    const parsed = ConfigSchema.parse(raw);
    expect(parsed).toStrictEqual(raw);
    expect(Object.keys(parsed)).toEqual(Object.keys(raw));
  });

  it("fills the same defaults for a minimal config", () => {
    expect(ConfigSchema.parse({ memoryDir: "/home/ada/memory" })).toStrictEqual(MINIMAL_PARSED_0_1_44);
  });

  it("is saved back byte for byte after a load", async () => {
    const { path, dir } = tempConfig();
    const raw = JSON.parse(FULL_0_1_44);
    raw.memoryDir = join(dir, "memory");
    const before = JSON.stringify(raw, null, 2) + "\n";
    writeFileSync(path, before);
    await saveConfig(await loadConfig());
    expect(readFileSync(path, "utf8")).toBe(before);
  });

  it("reads as no extra stores, the default server, no capture", () => {
    const cfg = ConfigSchema.parse(JSON.parse(FULL_0_1_44));
    expect(extraStores(cfg)).toEqual([]);
    expect(cfg.personaDir).toBeUndefined();
    expect(cfg.remote).toBeUndefined();
    expect(serverSettings(cfg)).toEqual({
      host: "127.0.0.1",
      port: 8787,
      auth: "none",
      maintenanceEveryMinutes: 60,
    });
    expect(captureSettings(cfg)).toEqual({
      hooks: false,
      nudgeEveryTurns: 10,
      extractOnCompact: true,
      serverNudge: false,
    });
  });
});

describe("the 0.2 fields", () => {
  it("parse with their defaults filled in", () => {
    const cfg = ConfigSchema.parse({
      memoryDir: "/m",
      personaDir: "/p",
      stores: [{ name: "team", dir: "/s" }],
      server: { port: 9000, auth: "bearer" },
      remote: { url: "https://memory.example.com/mcp" },
      capture: { hooks: true },
    });
    expect(cfg.stores).toEqual([{ name: "team", dir: "/s", write: false, git: true, gitAutoPush: false }]);
    expect(serverSettings(cfg)).toMatchObject({ host: "127.0.0.1", port: 9000, auth: "bearer" });
    expect(cfg.remote).toEqual({ url: "https://memory.example.com/mcp", tokenEnv: "AGENT_JULIA_TOKEN" });
    expect(captureSettings(cfg)).toMatchObject({ hooks: true, nudgeEveryTurns: 10 });
  });

  it("refuse a store name that could not be a page prefix", () => {
    for (const name of ["", "a", "Team", "team:x", "../x", "9team", "x".repeat(33)]) {
      expect(() => ConfigSchema.parse({ memoryDir: "/m", stores: [{ name, dir: "/s" }] })).toThrow();
    }
  });

  it("refuse two stores with the same name", () => {
    expect(() =>
      ConfigSchema.parse({
        memoryDir: "/m",
        stores: [
          { name: "team", dir: "/a" },
          { name: "team", dir: "/b" },
        ],
      }),
    ).toThrow(/duplicate store name/);
  });

  it("resolve personaDir and store dirs to absolute paths on load", async () => {
    const { path, dir } = tempConfig();
    writeFileSync(
      path,
      JSON.stringify({ memoryDir: join(dir, "m"), personaDir: "~/persona", stores: [{ name: "team", dir: "rel/store" }] }),
    );
    const cfg = await loadConfig();
    expect(cfg.personaDir).not.toContain("~");
    expect(cfg.stores![0]!.dir).toMatch(/rel[\\/]store$/);
    expect(cfg.stores![0]!.dir.startsWith(".")).toBe(false);
  });
});
